const ALLOWED = ["facebook","instagram","linkedin","twitter","threads","bluesky","tiktok","youtube"];
function parsePlatforms(raw) {
  const list = (Array.isArray(raw) ? raw : String(raw || '').split(','))
    .map((p) => String(p).trim().toLowerCase())
    .filter(Boolean)
    .map((p) => (p === 'x' ? 'twitter' : p));
  const unknown = list.filter((p) => !ALLOWED.includes(p));
  if (unknown.length) throw new Error('Socialync cannot post to: ' + unknown.join(', ') + '. Use: ' + ALLOWED.join(', ') + '.');
  if (!list.length) throw new Error('Set at least one platform in the Settings node.');
  return [...new Set(list)];
}
function fit(text, max) {
  const t = String(text).replace(/[ \t]+\n/g, '\n').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, Math.max(0, max - 3));
  return cut.replace(/\s+\S*$/, '') + '...';
}
// Socialync accepts 1 to 255 letters, digits and _ . : - in an Idempotency Key.
function safeKey(prefix, value) {
  return (prefix + ':' + String(value)).replace(/[^A-Za-z0-9_.:-]/g, '-').slice(0, 200);
}
const s = $('Settings').item.json;
const text = String($input.item.json.text || '').trim().replace(/^["']|["']$/g, '');
if (!text) throw new Error('The AI model sent back no text.');
const link = String(s.articleLink || '').trim();
if (!/^https?:\/\//i.test(link)) throw new Error('This feed item has no article link.');
const max = Math.max(100, Number(s.maxPostLength) || 300);
const caption = fit(text, Math.max(40, max - link.length - 2)) + '\n\n' + link;
const delay = Math.max(5, Number(s.publishDelayMinutes) || 720);
return { json: {
  profileId: String(s.profileId || '').trim(),
  platforms: parsePlatforms(s.platforms).filter((p) => !['tiktok', 'youtube'].includes(p)),
  caption,
  scheduledAt: new Date(Date.now() + delay * 60000).toISOString(),
  idempotencyKey: safeKey('rss', s.articleId || link),
} };
